import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static com.github.tomakehurst.wiremock.client.WireMock.verify;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.github.tomakehurst.wiremock.WireMockServer;
import com.github.tomakehurst.wiremock.client.WireMock;
import java.math.BigDecimal;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Verifies the wire-level contract with the payment provider: the exact JSON we
 * send, and how we interpret every answer shape the provider is documented to give
 * back (approved, declined, outright refusal, and anything unexpected).
 */
class HttpPaymentGatewayTest {

    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() {
        provider = new WireMockServer(0);
        provider.start();
        WireMock.configureFor("localhost", provider.port());

        var client = RestClient.builder().baseUrl(provider.baseUrl()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopProvider() {
        provider.stop();
    }

    @Test
    void sends_the_reference_amount_and_currency_as_json() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-1", new Money(new BigDecimal("42.50"), "EUR"));

        verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", WireMock.containing("application/json"))
                .withRequestBody(equalToJson(
                        "{\"reference\":\"ORD-1\",\"amount\":42.50,\"currency\":\"EUR\"}")));
    }

    @Test
    void an_approved_response_is_reported_as_approved() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        var outcome = gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_reported_as_declined() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"declined\"}")));

        var outcome = gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_request_outright_with_402_is_reported_as_declined() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(402)));

        var outcome = gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_status_value_in_the_body_is_treated_as_declined() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"pending\"}")));

        var outcome = gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_empty_body_is_treated_as_declined() {
        stubFor(WireMock.post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{}")));

        var outcome = gateway.authorize("ORD-6", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_server_error_other_than_402_is_surfaced_as_a_failure() {
